-- 由 scripts/gen-cloud-schema.mjs 自动生成；QW Pages Supabase 租户 schema，幂等
CREATE TABLE IF NOT EXISTS "action_center_hidden"(user_id TEXT,"item_id" TEXT,"hidden_at" TEXT,PRIMARY KEY(user_id,item_id));
